H.background();
const w = H.W, h = H.H;
const m = 1;
const k = Math.max(0.1, P.k), b = Math.max(0, P.b), A = P.A;
const omega0 = Math.sqrt(k / m);
const gamma = b / (2 * m);
// underdamped frequency (guard against over/critical damping)
const disc = omega0 * omega0 - gamma * gamma;
const omegaD = disc > 1e-6 ? Math.sqrt(disc) : 0;
const tw = t % 16; // loop the whole decay so it replays
function xOf(tau) {
  if (omegaD > 0) return A * Math.exp(-gamma * tau) * Math.cos(omegaD * tau);
  return A * Math.exp(-gamma * tau) * (1 + gamma * tau); // critical/over fallback
}
const x = xOf(tw);
// graph x(t) with the decaying envelope +/- A e^(-gamma t)
const v = H.plot2d({ xMin: 0, xMax: 16, yMin: -1.2 * Math.abs(A) - 0.3, yMax: 1.2 * Math.abs(A) + 0.3, box: { x: 60, y: 80, w: w - 120, h: h - 150 } });
v.grid(); v.axes();
v.fn(tau => A * Math.exp(-gamma * tau), { color: H.colors.warn, width: 1.5, steps: 200 });
v.fn(tau => -A * Math.exp(-gamma * tau), { color: H.colors.warn, width: 1.5, steps: 200 });
v.fn(xOf, { color: H.colors.accent, width: 3, steps: 300 });
v.dot(tw, x, { r: 6, fill: H.colors.good });
// little oscillating mass marker on the left axis
const mx = 40, my = v.Y(x);
H.circle(mx, my, 9, { fill: H.colors.good, stroke: H.colors.bg, width: 2 });
const regime = gamma < omega0 - 1e-6 ? "underdamped" : (gamma > omega0 + 1e-6 ? "overdamped" : "critically damped");
H.text("Damped oscillation:  x = A·e^(-gamma·t)·cos(omega_d·t)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("b = " + b.toFixed(2) + " kg/s   gamma = " + gamma.toFixed(2) + " 1/s   omega_d = " + omegaD.toFixed(2) + " rad/s   (" + regime + ")", 24, 54, { color: H.colors.sub, size: 13 });
H.legend([{ label: "x(t)", color: H.colors.accent }, { label: "envelope ±A·e^(-gamma·t)", color: H.colors.warn }], w - 250, 84);
